using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using PersonalFinance.Api.Application;
using PersonalFinance.Api.Contracts;
using PersonalFinance.Api.Domain;
using PersonalFinance.Api.Infrastructure;
using Xunit;
namespace PersonalFinance.Tests;
public partial class ConcertTests {
 [ProfileSqlFact] public async Task IndependentToursEnforceOwnershipVersionsAndLegacySceneCompatibility() {
  var connection=IsolatedSqlTestDatabase.ConnectionString();
  await using var db=new FinanceDb(new DbContextOptionsBuilder<FinanceDb>().UseSqlServer(connection).Options);await db.Database.MigrateAsync();
  var password="Tour-Test-"+Guid.NewGuid().ToString("N");
  AppUser User(){var u=new AppUser{Email=Guid.NewGuid().ToString("N")+"@tour.test",DisplayName="Tour test"};u.PasswordHash=new PasswordHasher<AppUser>().HashPassword(u,password);db.Add(u);return u;}
  var user=User();var other=User();await db.SaveChangesAsync();
  using var factory=new Factory(connection);using var client=factory.CreateClient();using var stranger=factory.CreateClient();
  foreach(var pair in new[]{(client,user),(stranger,other)}){var login=await Data(await pair.Item1.PostAsJsonAsync("/api/auth/login",new{email=pair.Item2.Email,password}));pair.Item1.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",login.GetProperty("accessToken").GetString());}
  Assert.Equal(HttpStatusCode.Forbidden,(await client.GetAsync("/api/concerts/tours")).StatusCode);
  await Data(await Write(client,"/settings/modules",new ConcertModules(true),put:true));await Data(await Write(stranger,"/settings/modules",new ConcertModules(true),put:true));
  var baseline=await db.Transactions.CountAsync();
  var tour=new ConcertTour("巡演测试","艺人",new(2026,1,1),new(2026,12,31),"Planned","");var key=Guid.NewGuid().ToString();
  var saved=await Data(await Write(client,"/concerts/tours",tour,key:key));var id=saved.GetProperty("id").GetString()!;var version=saved.GetProperty("version").GetString()!;
  Assert.Equal(id,(await Data(await Write(client,"/concerts/tours",tour,key:key))).GetProperty("id").GetString());
  Assert.Equal(HttpStatusCode.Conflict,(await Write(client,"/concerts/tours",tour with{Name="不同请求"},key:key)).StatusCode);
  Assert.Equal(0,(await Data(await client.GetAsync("/api/concerts/tours")))[0].GetProperty("sceneCount").GetInt32());
  Assert.Empty((await Data(await stranger.GetAsync("/api/concerts/tours"))).EnumerateArray());
  Assert.Equal(HttpStatusCode.NotFound,(await Write(stranger,"/concerts/tours/"+id,tour,version,put:true)).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(stranger,"/concerts",Scene() with{TourId=id})).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(client,"/concerts/tours",tour with{EndsOn=new(2025,1,1)})).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(client,"/concerts",Scene() with{TourId=Guid.NewGuid().ToString()})).StatusCode);
  var scene=await Data(await Write(client,"/concerts",Scene() with{TourId=id,TourName="客户端旧标题"}));var sceneId=scene.GetProperty("id").GetString()!;
  var detail=await Data(await client.GetAsync("/api/concerts/"+sceneId));Assert.Equal("巡演测试",detail.GetProperty("input").GetProperty("tourName").GetString());
  Assert.Equal(1,(await Data(await client.GetAsync("/api/concerts/tours")))[0].GetProperty("sceneCount").GetInt32());
  var update=await Data(await Write(client,"/concerts/tours/"+id,tour with{State="Completed"},version,put:true));
  Assert.Equal(HttpStatusCode.Conflict,(await Write(client,"/concerts/tours/"+id,tour,version,put:true)).StatusCode);
  await Data(await Write(client,"/concerts/"+sceneId,Scene() with{TourId=null},scene.GetProperty("version").GetString()!,put:true));
  Assert.Equal(0,(await Data(await client.GetAsync("/api/concerts/tours")))[0].GetProperty("sceneCount").GetInt32());
  var legacyId=Guid.NewGuid().ToString();var legacy=new StoredDocument{UserId=user.Id,Kind="ConcertScene",ContentType="application/json",Content=System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(Scene() with{TourId=legacyId},FinanceService.Json)};db.Add(legacy);await db.SaveChangesAsync();
  await Data(await Write(client,"/concerts/"+legacy.Id,Scene() with{TourId=legacyId},legacy.Version.ToString(),put:true));
  Assert.Equal(baseline,await db.Transactions.CountAsync());
  Assert.True(await db.AuditRecords.AnyAsync(x=>x.UserId==user.Id && x.ResourceId==id && x.Action=="TourUpdated"));
  Assert.Empty((await Data(await client.GetAsync("/api/concerts/tours/"+id+"/report"))).GetProperty("currencies").EnumerateArray());
  Assert.Equal(HttpStatusCode.NotFound,(await stranger.GetAsync("/api/concerts/tours/"+id+"/report")).StatusCode);
  var cash=new Account{UserId=user.Id,Name="巡演测试现金",Type="Cash",Currency="CNY",OpeningBalance=1000};
  var usd=new Account{UserId=user.Id,Name="巡演测试美元",Type="Cash",Currency="USD",OpeningBalance=1000};
  var parent=new Category{UserId=user.Id,Name="巡演测试",Kind="Expense"};
  var category=new Category{UserId=user.Id,Name="巡演测试费用",Kind="Expense",ParentId=parent.Id};db.AddRange(cash,usd,parent,category);await db.SaveChangesAsync();
  var date=new DateTimeOffset(2026,1,1,10,0,0,TimeSpan.FromHours(8));
  var payment=(await Data(await Write(client,"/transactions/expense",new SaveTransaction("Expense","100",cash.Id,date,CategoryId:category.Id)))).GetProperty("id").GetString()!;
  var foreignPayment=(await Data(await Write(client,"/transactions/expense",new SaveTransaction("Expense","30",usd.Id,date,CategoryId:category.Id)))).GetProperty("id").GetString()!;
  var refund=(await Data(await Write(client,"/transactions/refund",new SaveTransaction("Refund","20",cash.Id,date,CategoryId:category.Id,OriginalTransactionId:payment)))).GetProperty("id").GetString()!;
  var cost=new ConcertCost(Guid.NewGuid().ToString(),"Ticket",payment,null,"40","本人","本人");
  var first=await Data(await Write(client,"/concerts",Scene() with{TourId=id,Costs=[cost],Refunds=[new(Guid.NewGuid().ToString(),cost.Id,"Full","20","0",refund,"20","")],Plans=[new(Guid.NewGuid().ToString(),"Transport","未发生计划","10","Planned",null)]}));
  await Data(await Write(client,"/concerts",Scene() with{TourId=id,Title="第二场",Costs=[cost with{Id=Guid.NewGuid().ToString(),Amount="60"}]}));
  await Data(await Write(client,"/concerts",Scene() with{TourId=id,Title="美元场",Currency="USD",Costs=[cost with{Id=Guid.NewGuid().ToString(),TransactionId=foreignPayment,Amount="30"}]}));
  var transactionsBeforeReport=await db.Transactions.CountAsync();
  var report=await Data(await client.GetAsync("/api/concerts/tours/"+id+"/report"));
  Assert.Equal(3,report.GetProperty("scenes").GetArrayLength());
  var cny=report.GetProperty("currencies").EnumerateArray().Single(x=>x.GetProperty("currency").GetString()=="CNY");
  Assert.Equal("100.00",cny.GetProperty("originalCosts").GetString());Assert.Equal("20.00",cny.GetProperty("confirmedRefunds").GetString());
  Assert.Equal("80.00",cny.GetProperty("actual").GetString());Assert.Equal("80.00",cny.GetProperty("personalNetCost").GetString());Assert.Equal("10.00",cny.GetProperty("planned").GetString());Assert.Equal("1920.00",cny.GetProperty("remaining").GetString());
  Assert.Equal("30.00",report.GetProperty("currencies").EnumerateArray().Single(x=>x.GetProperty("currency").GetString()=="USD").GetProperty("actual").GetString());
  Assert.Equal(first.GetProperty("id").GetString(),report.GetProperty("scenes").EnumerateArray().Single(x=>x.GetProperty("input").GetProperty("title").GetString()=="上海场").GetProperty("id").GetString());
  Assert.Equal(transactionsBeforeReport,await db.Transactions.CountAsync());
  db.ChangeTracker.Clear();var changed=await db.Transactions.SingleAsync(x=>x.Id==payment);changed.Status="NeedsReview";await db.SaveChangesAsync();
  report=await Data(await client.GetAsync("/api/concerts/tours/"+id+"/report"));
  Assert.Equal("0.00",report.GetProperty("currencies").EnumerateArray().Single(x=>x.GetProperty("currency").GetString()=="CNY").GetProperty("actual").GetString());
  Assert.Contains(report.GetProperty("scenes").EnumerateArray(),x=>x.GetProperty("report").GetProperty("warnings").GetArrayLength()>0);
  var timePayment=(await Data(await Write(client,"/transactions/expense",new SaveTransaction("Expense","10",cash.Id,date,CategoryId:category.Id)))).GetProperty("id").GetString()!;
  var localScene=Scene() with{Title="纽约跨年场",StartsAt=DateTimeOffset.Parse("2026-01-01T02:30:00Z"),TimeZone="America/New_York",Costs=[cost with{Id=Guid.NewGuid().ToString(),TransactionId=timePayment,Amount="10"}]};
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(client,"/concerts",localScene with{TimeZone="Invalid/Zone"})).StatusCode);
  var savedTime=await Data(await Write(client,"/concerts",localScene));var timeId=savedTime.GetProperty("id").GetString()!;
  var annual=await Data(await client.GetAsync("/api/concerts/report?year=2025&currency=CNY"));
  Assert.Equal(1,annual.GetProperty("count").GetInt32());Assert.Equal("10.00",annual.GetProperty("totalCost").GetString());
  Assert.Equal("10.00",annual.GetProperty("months")[11].GetProperty("cost").GetString());Assert.Equal("0.00",annual.GetProperty("months")[0].GetProperty("cost").GetString());
  Assert.Equal("America/New_York",annual.GetProperty("scenes")[0].GetProperty("timeZone").GetString());
  savedTime=await Data(await Write(client,"/concerts/"+timeId,localScene with{TimeZone=null},savedTime.GetProperty("version").GetString()!,put:true));
  Assert.Equal("America/New_York",(await Data(await client.GetAsync("/api/concerts/"+timeId))).GetProperty("input").GetProperty("timeZone").GetString());
  await Data(await Write(client,"/concerts/"+timeId,localScene with{TimeZone="Asia/Shanghai"},savedTime.GetProperty("version").GetString()!,put:true));
  Assert.Equal(0,(await Data(await client.GetAsync("/api/concerts/report?year=2025&currency=CNY"))).GetProperty("count").GetInt32());
  var savedDetail=await Data(await client.GetAsync("/api/concerts/"+timeId));
  Assert.Equal(localScene.StartsAt,savedDetail.GetProperty("input").GetProperty("startsAt").GetDateTimeOffset());
  Assert.Contains((await Data(await client.GetAsync("/api/concerts/"+timeId+"/history"))).EnumerateArray(),x=>x.GetProperty("action").GetString()=="ScheduleUpdated");
 }
}
